  /**
   * @method
   * @name p2b#fetchMarkets
   * @description retrieves data on all markets for p2b
   * @see
   * https://github.com/P2B-team/p2b-api-docs/blob/master/api-doc.md#markets
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object[]} an array of objects representing market data
   */
  std::shared_future<std::any>
  fetchMarkets(std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        std::any response =
                            awaitValue(this->publicGetMarkets(params));
                        //
                        //    {
                        //        "success": true,
                        //        "errorCode": "",
                        //        "message": "",
                        //        "result": [
                        //            {
                        //                "name": "ETH_BTC",
                        //                "stock": "ETH",
                        //                "money": "BTC",
                        //                "precision": {
                        //                    "money": "5",
                        //                    "stock": "4",
                        //                    "fee": "4"
                        //                },
                        //                "limits": {
                        //                    "min_amount": "0.0001",
                        //                    "max_amount": "100000",
                        //                    "step_size": "0.0001",
                        //                    "min_price": "0.00001",
                        //                    "max_price": "922327",
                        //                    "tick_size": "0.00001",
                        //                    "min_total": "0.0001"
                        //                }
                        //            },
                        //            ...
                        //        ]
                        //    }
                        //
                        std::any markets = this->safeList(
                            response, std::string("result"), ccxt::list{});
                        return this->parseMarkets(markets);
                      })
        .share();
  }

  std::any parseMarket(std::any market) override {
    std::any marketId = this->safeString(market, std::string("name"));
    std::any baseId = this->safeString(market, std::string("stock"));
    std::any quoteId = this->safeString(market, std::string("money"));
    std::any base = this->safeCurrencyCode(baseId);
    std::any quote = this->safeCurrencyCode(quoteId);
    std::any limits = this->safeDict(market, std::string("limits"));
    std::any maxAmount = this->safeString(limits, std::string("max_amount"));
    std::any maxPrice = this->safeString(limits, std::string("max_price"));
    return ccxt::dict{
        {std::string("id"), marketId},
        {std::string("symbol"), add(add(base, std::string("/")), quote)},
        {std::string("base"), base},
        {std::string("quote"), quote},
        {std::string("settle"), std::any{}},
        {std::string("baseId"), baseId},
        {std::string("quoteId"), quoteId},
        {std::string("settleId"), std::any{}},
        {std::string("type"), std::string("spot")},
        {std::string("spot"), true},
        {std::string("margin"), false},
        {std::string("swap"), false},
        {std::string("future"), false},
        {std::string("option"), false},
        {std::string("active"), true},
        {std::string("contract"), false},
        {std::string("linear"), std::any{}},
        {std::string("inverse"), std::any{}},
        {std::string("contractSize"), std::any{}},
        {std::string("expiry"), std::any{}},
        {std::string("expiryDatetime"), std::any{}},
        {std::string("strike"), std::any{}},
        {std::string("optionType"), std::any{}},
        {std::string("precision"),
         ccxt::dict{
             {std::string("amount"),
              this->safeNumber(limits, std::string("step_size"))},
             {std::string("price"),
              this->safeNumber(limits, std::string("tick_size"))},
         }},
        {std::string("limits"),
         ccxt::dict{
             {std::string("leverage"),
              ccxt::dict{
                  {std::string("min"), std::any{}},
                  {std::string("max"), std::any{}},
              }},
             {std::string("amount"),
              ccxt::dict{
                  {std::string("min"),
                   this->safeNumber(limits, std::string("min_amount"))},
                  {std::string("max"),
                   this->parseNumber(this->omitZero(maxAmount))},
              }},
             {std::string("price"),
              ccxt::dict{
                  {std::string("min"),
                   this->safeNumber(limits, std::string("min_price"))},
                  {std::string("max"),
                   this->parseNumber(this->omitZero(maxPrice))},
              }},
             {std::string("cost"),
              ccxt::dict{
                  {std::string("min"),
                   this->safeNumber(limits, std::string("min_total"))},
                  {std::string("max"), std::any{}},
              }},
         }},
        {std::string("created"), std::any{}},
        {std::string("info"), market},
    };
  }

  /**
   * @method
   * @name p2b#fetchTickers
   * @description fetches price tickers for multiple markets, statistical
   * information calculated over the past 24 hours for each market
   * @see
   * https://github.com/P2B-team/p2b-api-docs/blob/master/api-doc.md#tickers
   * @param {string[]|undefined} symbols unified symbols of the markets to fetch
   * the ticker for, all market tickers are returned if not assigned
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a dictionary of [ticker structures]{@link
   * https://docs.ccxt.com/?id=ticker-structure}
   */
  std::shared_future<std::any>
  fetchTickers(std::any symbols = std::any{},
               std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        std::any response =
                            awaitValue(this->publicGetTickers(params));
                        //
                        //    {
                        //        success: true,
                        //        errorCode: '',
                        //        message: '',
                        //        result: {
                        //            KNOLIX_BTC: {
                        //                at: '1699252631',
                        //                ticker: {
                        //                    bid: '0.0000332',
                        //                    ask: '0.0000333',
                        //                    low: '0.0000301',
                        //                    high: '0.0000338',
                        //                    last: '0.0000333',
                        //                    vol: '15.66',
                        //                    deal: '0.000501828',
                        //                    change: '10.63'
                        //                }
                        //            },
                        //            ...
                        //        },
                        //        cache_time: '1699252631.103631',
                        //        current_time: '1699252644.487566'
                        //    }
                        //
                        std::any result = this->safeValue(
                            response, std::string("result"), ccxt::dict{});
                        return this->parseTickers(result, symbols);
                      })
        .share();
  }

