  /**
   * @method
   * @name p2b#fetchTrades
   * @description get the list of most recent trades for a particular symbol
   * @see
   * https://github.com/P2B-team/p2b-api-docs/blob/master/api-doc.md#history
   * @param {string} symbol unified symbol of the market to fetch trades for
   * @param {int} [since] timestamp in ms of the earliest trade to fetch
   * @param {int} [limit] 1-100, default=50
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} params.lastId order id
   * @returns {Trade[]} a list of [trade structures]{@link
   * https://docs.ccxt.com/?id=public-trades}
   */
  std::shared_future<std::any>
  fetchTrades(std::any symbol, std::any since = std::any{},
              std::any limit = std::any{},
              std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        std::any lastId =
                            this->safeInteger(params, std::string("lastId"));
                        if (isTrue(isEqual(lastId, std::any{}))) {
                          throw ArgumentsRequired(toString(add(
                              this->id,
                              std::string(" fetchTrades () requires an extra "
                                          "parameter params[\"lastId\"]"))));
                        }
                        std::any market = this->market(symbol);
                        std::any request = ccxt::dict{
                            {std::string("market"),
                             ::getValue(market, std::string("id"))},
                            {std::string("lastId"), lastId},
                        };
                        if (isTrue(!isEqual(limit, std::any{}))) {
                          ::setValue(request, std::string("limit"), limit);
                        }
                        std::any response = awaitValue(this->publicGetHistory(
                            this->extend(request, params)));
                        //
                        //    {
                        //        success: true,
                        //        errorCode: '',
                        //        message: '',
                        //        result: [
                        //            {
                        //                id: '7495738622',
                        //                type: 'sell',
                        //                time: '1699255565.445418',
                        //                amount: '252.6',
                        //                price: '0.3422'
                        //            },
                        //            ...
                        //        ],
                        //        cache_time: '1699255571.413633',
                        //        current_time: '1699255571.413828'
                        //    }
                        //
                        std::any result = this->safeList(
                            response, std::string("result"), ccxt::list{});
                        return this->parseTrades(result, market, since, limit);
                      })
        .share();
  }

  std::any parseTrade(std::any trade, std::any market = std::any{}) override {
    //
    // fetchTrades
    //
    //    {
    //        id: '7495738622',
    //        type: 'sell',
    //        time: '1699255565.445418',
    //        amount: '252.6',
    //        price: '0.3422'
    //    }
    //
    // fetchMyTrades
    //
    //    {
    //        "deal_id": 7450617292,              // Deal id
    //        "deal_time": 1698506956.66224,      // Deal execution time
    //        "deal_order_id": 171955225751,      // Deal order id
    //        "opposite_order_id": 171955110512,  // Opposite order id
    //        "side": "sell",                     // Deal side
    //        "price": "0.05231",                 // Deal price
    //        "amount": "0.002",                  // Deal amount
    //        "deal": "0.00010462",               // Total (price * amount)
    //        "deal_fee": "0.000000188316",       // Deal fee
    //        "role": "taker",                    // Role. Taker or maker
    //        "isSelfTrade": false                // is self trade
    //    }
    //
    // fetchOrderTrades
    //
    //    {
    //        "id": 7429883128,             // Deal id
    //        "time": 1698237535.41196,     // Deal execution time
    //        "fee": "0.01755848704",       // Deal fee
    //        "price": "34293.92",          // Deal price
    //        "amount": "0.00032",          // Deal amount
    //        "dealOrderId": 171366551416,  // Deal order id
    //        "role": 1,                    // Deal role (1 - maker, 2 - taker)
    //        "deal": "10.9740544"          // Total (price * amount)
    //    }
    //
    std::any timestamp = this->safeIntegerProduct2(
        trade, std::string("time"), std::string("deal_time"), 1000);
    std::any takerOrMaker = this->safeString(trade, std::string("role"));
    if (isTrue(isEqual(takerOrMaker, std::string("1")))) {
      takerOrMaker = std::string("maker");
    } else if (isTrue(isEqual(takerOrMaker, std::string("2")))) {
      takerOrMaker = std::string("taker");
    }
    return this->safeTrade(
        ccxt::dict{
            {std::string("info"), trade},
            {std::string("id"), this->safeString2(trade, std::string("id"),
                                                  std::string("deal_id"))},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("symbol"),
             this->safeString(market, std::string("symbol"))},
            {std::string("order"),
             this->safeString2(trade, std::string("dealOrderId"),
                               std::string("deal_order_id"))},
            {std::string("type"), std::any{}},
            {std::string("side"), this->safeString2(trade, std::string("type"),
                                                    std::string("side"))},
            {std::string("takerOrMaker"), takerOrMaker},
            {std::string("price"),
             this->safeString(trade, std::string("price"))},
            {std::string("amount"),
             this->safeString(trade, std::string("amount"))},
            {std::string("cost"), this->safeString(trade, std::string("deal"))},
            {std::string("fee"),
             ccxt::dict{
                 {std::string("currency"),
                  this->safeString(market, std::string("quote"))},
                 {std::string("cost"),
                  this->safeString2(trade, std::string("fee"),
                                    std::string("deal_fee"))},
             }},
        },
        market);
  }

  /**
   * @method
   * @name p2b#fetchOHLCV
   * @description fetches historical candlestick data containing the open, high,
   * low, and close price, and the volume of a market
   * @see https://github.com/P2B-team/p2b-api-docs/blob/master/api-doc.md#kline
   * @param {string} symbol unified symbol of the market to fetch OHLCV data for
   * @param {string} timeframe 1m, 1h, or 1d
   * @param {int} [since] timestamp in ms of the earliest candle to fetch
   * @param {int} [limit] 1-500, default=50
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.offset] default=0, with this value the last candles
   * are returned
   * @returns {int[][]} A list of candles ordered as timestamp, open, high, low,
   * close, volume
   */
  std::shared_future<std::any>
  fetchOHLCV(std::any symbol, std::any timeframe = std::string("1m"),
             std::any since = std::any{}, std::any limit = std::any{},
             std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        std::any market = this->market(symbol);
                        std::any request = ccxt::dict{
                            {std::string("market"),
                             ::getValue(market, std::string("id"))},
                            {std::string("interval"), timeframe},
                        };
                        if (isTrue(!isEqual(limit, std::any{}))) {
                          ::setValue(request, std::string("limit"), limit);
                        }
                        std::any response =
                            awaitValue(this->publicGetMarketKline(
                                this->extend(request, params)));
                        //
                        //    {
                        //        success: true,
                        //        errorCode: '',
                        //        message: '',
                        //        result: [
                        //            [
                        //                1699253400,       // Kline open time
                        //                '0.3429',         // Open price
                        //                '0.3427',         // Close price
                        //                '0.3429',         // Highest price
                        //                '0.3427',         // Lowest price
                        //                '1900.4',         // Volume for stock
                        //                currency '651.46278',      // Volume
                        //                for money currency 'ADA_USDT' //
                        //                Market name
                        //            ],
                        //            ...
                        //        ],
                        //        cache_time: '1699256375.030292',
                        //        current_time: '1699256375.030494'
                        //    }
                        //
                        std::any result = this->safeList(
                            response, std::string("result"), ccxt::list{});
                        return this->parseOHLCVs(result, market, timeframe,
                                                 since, limit);
                      })
        .share();
  }

  std::any parseOHLCV(std::any ohlcv, std::any market = std::any{}) override {
    //
    //    [
    //        1699253400,       // Kline open time
    //        '0.3429',         // Open price
    //        '0.3427',         // Close price
    //        '0.3429',         // Highest price
    //        '0.3427',         // Lowest price
    //        '1900.4',         // Volume for stock currency
    //        '651.46278',      // Volume for money currency
    //        'ADA_USDT'        // Market name
    //    ],
    //
    return ccxt::list{this->safeIntegerProduct(ohlcv, 0, 1000),
                      this->safeNumber(ohlcv, 1),
                      this->safeNumber(ohlcv, 3),
                      this->safeNumber(ohlcv, 4),
                      this->safeNumber(ohlcv, 2),
                      this->safeNumber(ohlcv, 5)};
  }

  /**
   * @method
   * @name p2b#fetchBalance
   * @description query for balance and get the amount of funds available for
   * trading or funds locked in orders
   * @see
   * https://github.com/P2B-team/p2b-api-docs/blob/master/api-doc.md#all-balances
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [balance structure]{@link
   * https://docs.ccxt.com/?id=balance-structure}
   */
  std::shared_future<std::any>
  fetchBalance(std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        std::any response = awaitValue(
                            this->privatePostAccountBalances(params));
                        //
                        //    {
                        //        "success": true,
                        //        "errorCode": "",
                        //        "message": "",
                        //        "result": {
                        //            "USDT": {
                        //              "available": "71.81328046",
                        //              "freeze": "10.46103091"
                        //            },
                        //            "BTC": {
                        //              "available": "0.00135674",
                        //              "freeze": "0.00020003"
                        //            }
                        //        }
                        //    }
                        //
                        std::any result = this->safeValue(
                            response, std::string("result"), ccxt::dict{});
                        return this->parseBalance(result);
                      })
        .share();
  }

  std::any parseBalance(std::any response) override {
    //
    //    {
    //        "USDT": {
    //            "available": "71.81328046",
    //            "freeze": "10.46103091"
    //        },
    //        "BTC": {
    //            "available": "0.00135674",
    //            "freeze": "0.00020003"
    //        }
    //    }
    //
    std::any result = ccxt::dict{
        {std::string("info"), response},
    };
    std::any keys = getObjectKeys(response);
    for (std::any i = 0; isLessThan(i, getArrayLength(keys));
         postFixIncrement(i)) {
      std::any currencyId = ::getValue(keys, i);
      std::any balance = ::getValue(response, currencyId);
      std::any code = this->safeCurrencyCode(currencyId);
      std::any used = this->safeString(balance, std::string("freeze"));
      std::any available = this->safeString(balance, std::string("available"));
      std::any account = ccxt::dict{
          {std::string("free"), available},
          {std::string("used"), used},
      };
      ::setValue(result, code, account);
    }
    return this->safeBalance(result);
  }

  /**
   * @method
   * @name p2b#createOrder
   * @description create a trade order
   * @see
   * https://github.com/P2B-team/p2b-api-docs/blob/master/api-doc.md#create-order
   * @param {string} symbol unified symbol of the market to create an order in
   * @param {string} type must be 'limit'
   * @param {string} side 'buy' or 'sell'
   * @param {float} amount how much of currency you want to trade in units of
   * base currency
   * @param {float} price the price at which the order is to be fulfilled, in
   * units of the quote currency
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  createOrder(std::any symbol, std::any type, std::any side, std::any amount,
              std::any price = std::any{},
              std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 if (isTrue(isEqual(type, std::string("market")))) {
                   throw BadRequest(toString(add(
                       this->id, std::string(" createOrder () can only accept "
                                             "orders with type \"limit\""))));
                 }
                 std::any market = this->market(symbol);
                 std::any request = ccxt::dict{
                     {std::string("market"),
                      ::getValue(market, std::string("id"))},
                     {std::string("side"), side},
                     {std::string("amount"),
                      this->amountToPrecision(symbol, amount)},
                     {std::string("price"),
                      this->priceToPrecision(symbol, price)},
                 };
                 std::any response = awaitValue(
                     this->privatePostOrderNew(this->extend(request, params)));
                 //
                 //    {
                 //        "success": true,
                 //        "errorCode": "",
                 //        "message": "",
                 //        "result": {
                 //            "orderId": 171906478744,          // Order id
                 //            "market": "ETH_BTC",              // Market name
                 //            "price": "0.04348",               // Price
                 //            "side": "buy",                    // Side
                 //            "type": "limit",                  // Order type
                 //            "timestamp": 1698484861.746517,   // Order
                 //            creation time "dealMoney": "0", // Filled total
                 //            "dealStock": "0",                 // Filled
                 //            amount "amount": "0.0277",               //
                 //            Original amount "takerFee": "0.002", // taker fee
                 //            "makerFee": "0.002",              // maker fee
                 //            "left": "0.0277",                 // Unfilled
                 //            amount "dealFee": "0"                    //
                 //            Filled fee
                 //        }
                 //    }
                 //
                 std::any result =
                     this->safeDict(response, std::string("result"));
                 return this->parseOrder(result, market);
               })
        .share();
  }

